  ('sensory_descriptor', 'wood_vanilla', '나무·바닐라', null, array[]::text[], null, array['aroma', 'finish', 'palate']::text[], '{"onboarding_selectable":false,"sensory_description":"나무 냄새에 바닐라 향이 섞여 포근하게 느껴지는 향입니다.","sensory_service":{"status":"pending","version":"2.0.0"},"sensory_trait_keys":["sweet_scent","woody_scent"],"user_visible":false}'::jsonb, '4.0.0', 2520, true),
  ('sensory_descriptor', 'yellow_fruit', '노란 과일', null, array[]::text[], null, array['aroma', 'finish', 'palate']::text[], '{"onboarding_selectable":false,"sensory_description":"복숭아나 바나나처럼 부드럽고 달콤한 과일 향입니다.","sensory_service":{"status":"hidden","version":"2.0.0"},"sensory_trait_keys":["fruit_scent"],"user_visible":false}'::jsonb, '4.0.0', 2530, true)
) as v(term_type, term_key, label_ko, label_en, synonyms, parent_term_key,
  applicable_sections, metadata, taxonomy_version, sort_order, is_active)
where not exists (
  select 1 from jsonb_array_elements_text(v.metadata->'applies_to_categories') as wanted(category_key)
  where not exists (
    select 1 from public.alcohol_categories category
    where category.category_key = wanted.category_key and category.is_active
  )
)
on conflict (term_type, term_key) do update
set label_ko = excluded.label_ko,
    label_en = excluded.label_en,
    synonyms = excluded.synonyms,
    parent_term_key = excluded.parent_term_key,
    applicable_sections = excluded.applicable_sections,
    -- DB-edited descriptions/traits remain authoritative during taxonomy reseeds.
    metadata = excluded.metadata || jsonb_strip_nulls(jsonb_build_object(
      'sensory_description', catalog_terms.metadata->'sensory_description',
      'sensory_trait_keys', catalog_terms.metadata->'sensory_trait_keys'
    )),
    taxonomy_version = excluded.taxonomy_version,
    sort_order = excluded.sort_order,
    is_active = excluded.is_active,
    updated_at = now();


